contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _owner) public {
        bool success;
        try c.setOwner(_owner) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }
        assert(success && c.owner() == _owner);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _owner) public payable {
        bool reverted;
        try c.setOwner(_owner) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The contract's admin is set to the InvMutTest contract (msg.sender in C's constructor,
        // and InvMutTest deployed C), so the setOwner call from this contract must succeed and
        // update owner to _owner. It can never revert, and owner is _owner after the call.
        assert(!reverted && c.owner() == _owner);
    }

    receive() external payable {}
}

